CREATE TABLE public.review_notifications (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, org_id uuid NOT NULL REFERENCES public.organizations(id), event_key text NOT NULL, kind text NOT NULL, title text NOT NULL, detail text NOT NULL, purchase_id uuid REFERENCES public.purchases(id), change_request_id uuid REFERENCES public.supplier_change_requests(id), purchase_version integer, created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz, UNIQUE(user_id,event_key)
);
GRANT SELECT ON public.review_notifications TO authenticated;
GRANT ALL ON public.review_notifications TO service_role;
ALTER TABLE public.review_notifications ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_read_review_notification(_user uuid,_org uuid,_kind text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid()=_user AND EXISTS(SELECT 1 FROM memberships WHERE user_id=auth.uid() AND org_id=_org AND (_kind NOT IN ('spending_review','supplier_review') OR role='owner' OR (_kind='spending_review' AND role='payer') OR (_kind='supplier_review' AND role='change_approver'))) $$;
REVOKE ALL ON FUNCTION public.can_read_review_notification(uuid,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_read_review_notification(uuid,uuid,text) TO authenticated;
CREATE POLICY own_eligible_notifications ON public.review_notifications FOR SELECT TO authenticated USING (public.can_read_review_notification(user_id,org_id,kind));
CREATE FUNCTION public.mark_review_notification_read(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE review_notifications SET read_at=coalesce(read_at,now()) WHERE id=_id AND public.can_read_review_notification(user_id,org_id,kind); IF NOT FOUND THEN RAISE EXCEPTION 'Notification unavailable or permission removed'; END IF; END $$;
REVOKE ALL ON FUNCTION public.mark_review_notification_read(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.mark_review_notification_read(uuid) TO authenticated;
CREATE FUNCTION public.deliver_pending_purchase_review(_pid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p purchases%rowtype; BEGIN SELECT * INTO p FROM purchases WHERE id=_pid; IF p.status<>'approval_required' THEN RETURN; END IF; INSERT INTO review_notifications(user_id,org_id,event_key,kind,title,detail,purchase_id,purchase_version)
 SELECT DISTINCT m.user_id,p.org_id,'spending:'||p.id||':v'||p.version||':policy:'||coalesce(p.policy_version_id::text,'none'),'spending_review','Spending review required',coalesce(p.invoice_reference,p.fixture_label,p.title)||' — review the current request and approve or reject spending.',p.id,p.version FROM memberships m WHERE m.org_id=p.org_id AND m.role IN ('payer','owner') AND m.user_id<>p.requested_by ON CONFLICT(user_id,event_key) DO NOTHING; END $$;
CREATE FUNCTION public.deliver_pending_supplier_review(_cid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c supplier_change_requests%rowtype; p purchases%rowtype; BEGIN SELECT * INTO c FROM supplier_change_requests WHERE id=_cid; SELECT * INTO p FROM purchases WHERE id=c.purchase_id; IF c.status NOT IN ('pending_verification','verified_pending_decision') OR (c.purchase_id IS NOT NULL AND (p.status IN ('paid','cancelled') OR p.requested_recipient IS DISTINCT FROM c.proposed_recipient)) THEN RETURN; END IF;
 INSERT INTO review_notifications(user_id,org_id,event_key,kind,title,detail,purchase_id,change_request_id,purchase_version) SELECT DISTINCT m.user_id,c.org_id,'supplier:'||c.id||':'||c.status,'supplier_review','Supplier payment-detail review required',coalesce(p.invoice_reference,p.fixture_label,p.title,'Supplier proposal')||' — independently check payment details; reject unsupported details. Invoice content is not verification.',c.purchase_id,c.id,p.version FROM memberships m WHERE m.org_id=c.org_id AND m.role IN ('change_approver','owner') AND m.user_id<>c.proposed_by AND m.user_id IS DISTINCT FROM p.requested_by ON CONFLICT(user_id,event_key) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.deliver_pending_purchase_review(uuid),public.deliver_pending_supplier_review(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.notify_purchase_review_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM deliver_pending_purchase_review(NEW.id); RETURN NEW; END $$;
CREATE TRIGGER notify_purchase_review AFTER INSERT OR UPDATE ON public.purchases FOR EACH ROW EXECUTE FUNCTION public.notify_purchase_review_trigger();
CREATE FUNCTION public.notify_supplier_review_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM deliver_pending_supplier_review(NEW.id); RETURN NEW; END $$;
CREATE TRIGGER notify_supplier_review AFTER INSERT OR UPDATE ON public.supplier_change_requests FOR EACH ROW EXECUTE FUNCTION public.notify_supplier_review_trigger();
CREATE FUNCTION public.notify_review_outcome_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p purchases%rowtype; c supplier_change_requests%rowtype; pid uuid; recipient uuid; cid uuid; label text; reason text; BEGIN
 IF NEW.action NOT IN ('purchase_approved','spending_rejected','supplier_change_approved','supplier_change_rejected','approval_invalidated') THEN RETURN NEW; END IF;
 IF NEW.action LIKE 'supplier_change_%' THEN cid=(NEW.details->>'change_request')::uuid; SELECT * INTO c FROM supplier_change_requests WHERE id=cid; pid=c.purchase_id; recipient=c.proposed_by; reason=c.decision_note; ELSE pid=NEW.entity_id; END IF;
 SELECT * INTO p FROM purchases WHERE id=pid; recipient=coalesce(recipient,p.requested_by); IF recipient IS NULL THEN RETURN NEW; END IF;
 label=CASE NEW.action WHEN 'purchase_approved' THEN 'Spending approved' WHEN 'spending_rejected' THEN 'Spending rejected' WHEN 'supplier_change_approved' THEN 'Supplier change verified' WHEN 'supplier_change_rejected' THEN 'Supplier change rejected' ELSE 'Spending approval no longer valid' END;
 INSERT INTO review_notifications(user_id,org_id,event_key,kind,title,detail,purchase_id,change_request_id,purchase_version,created_at) VALUES(recipient,NEW.org_id,'decision:'||NEW.id,'outcome',label,coalesce(p.invoice_reference,p.fixture_label,p.title,'Supplier proposal')||' — '||label||CASE WHEN coalesce(reason,NEW.details->>'reason','')<>'' THEN '. Reason: '||coalesce(reason,NEW.details->>'reason') ELSE '' END,pid,cid,coalesce(NEW.entity_version,p.version),NEW.created_at) ON CONFLICT(user_id,event_key) DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER notify_review_outcome AFTER INSERT ON public.audit_events FOR EACH ROW EXECUTE FUNCTION public.notify_review_outcome_trigger();
CREATE FUNCTION public.notify_new_review_member() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; BEGIN FOR r IN SELECT id FROM purchases WHERE org_id=NEW.org_id AND status='approval_required' LOOP PERFORM deliver_pending_purchase_review(r.id); END LOOP; FOR r IN SELECT id FROM supplier_change_requests WHERE org_id=NEW.org_id AND status IN ('pending_verification','verified_pending_decision') LOOP PERFORM deliver_pending_supplier_review(r.id); END LOOP; RETURN NEW; END $$;
CREATE TRIGGER notify_review_member AFTER INSERT OR UPDATE ON public.memberships FOR EACH ROW EXECUTE FUNCTION public.notify_new_review_member();
REVOKE ALL ON FUNCTION public.notify_purchase_review_trigger(),public.notify_supplier_review_trigger(),public.notify_review_outcome_trigger(),public.notify_new_review_member() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE r record; BEGIN FOR r IN SELECT id FROM purchases WHERE status='approval_required' LOOP PERFORM public.deliver_pending_purchase_review(r.id); END LOOP; FOR r IN SELECT id FROM supplier_change_requests WHERE status IN ('pending_verification','verified_pending_decision') LOOP PERFORM public.deliver_pending_supplier_review(r.id); END LOOP; END $$;